-- Deal step 5b: civilization builds
-- Generated by scripts/generate/generate.mjs from shared/deal/ (workstream B). Don't edit by hand.

CREATE TABLE IF NOT EXISTS LShufWork_CivInfo (Civ TEXT PRIMARY KEY, Age TEXT, Play TEXT, Ability TEXT, AbilityName TEXT, Base TEXT, Tree TEXT, TreeReq TEXT);
DELETE FROM LShufWork_CivInfo;
  SELECT ct.CivilizationType, COALESCE((SELECT MIN(lc.Age) FROM LegacyCivilizations lc WHERE lc.CivilizationType = ct.CivilizationType), ''),
    MIN(ct.TraitType)
  FROM CivilizationTraits ct
  WHERE ct.TraitType LIKE 'TRAIT\_%\_ABILITY' ESCAPE '\' AND ct.CivilizationType IN (SELECT CivilizationType FROM Civilizations)
  GROUP BY ct.CivilizationType;
-- A builder's civ plays in the game's age (lshuf-deal-civ.js playAge; Test of Time lets a civ from another age start).
UPDATE LShufWork_CivInfo SET Play = (SELECT Value FROM LShufOptions WHERE Name = 'Age')
  WHERE COALESCE((SELECT Value FROM LShufOptions WHERE Name = 'Age'), '') <> ''
    AND Civ IN (SELECT Civ FROM LShufWork_Build WHERE OK = 1);
UPDATE LShufWork_CivInfo SET Base = substr(Ability, 1, length(Ability) - 8),
  AbilityName = (SELECT t.Name FROM Traits t WHERE t.TraitType = LShufWork_CivInfo.Ability);
-- The civics tree a civ's base trait reveals (CONTRACTS 18): the reveal modifier whose subject requirement asks for the
-- trait, and that requirement's id (its TraitType argument is what moves the tree).
UPDATE LShufWork_CivInfo SET TreeReq = (SELECT MIN(ra.RequirementId) FROM Modifiers m
    JOIN ModifierArguments ma ON ma.ModifierId = m.ModifierId AND ma.Name = 'ProgressionTreeType'
    JOIN RequirementSetRequirements rsr ON rsr.RequirementSetId = m.SubjectRequirementSetId
    JOIN Requirements r ON r.RequirementId = rsr.RequirementId AND r.RequirementType = 'REQUIREMENT_PLAYER_HAS_CIVILIZATION_OR_LEADER_TRAIT'
    JOIN RequirementArguments ra ON ra.RequirementId = r.RequirementId AND ra.Name = 'TraitType'
    WHERE ra.Value = LShufWork_CivInfo.Base AND ma.Value LIKE 'TREE\_CIVICS\_%' ESCAPE '\');
UPDATE LShufWork_CivInfo SET Tree = (SELECT MIN(ma.Value) FROM ModifierArguments ma JOIN Modifiers m ON m.ModifierId = ma.ModifierId
    JOIN RequirementSetRequirements rsr ON rsr.RequirementSetId = m.SubjectRequirementSetId
    WHERE ma.Name = 'ProgressionTreeType' AND rsr.RequirementId = LShufWork_CivInfo.TreeReq) WHERE TreeReq IS NOT NULL;
-- A unit family only the civ's own civics tree unlocks (Mississippi's Watonathi) belongs to the civics (CONTRACTS 18):
-- every member of such a family, so the uniques part leaves it alone and it stays on the base trait.
CREATE TABLE IF NOT EXISTS LShufWork_CivicUnit (UnitType TEXT PRIMARY KEY);
DELETE FROM LShufWork_CivicUnit;
-- A great person whose class asks for a quarter (its BuildingType1) or constructible a civ civics tree unlocks belongs
-- to the civics too (CONTRACTS 23 R1): every member of its family, with the type that ties it.
CREATE TABLE IF NOT EXISTS LShufWork_CivicGP (UnitType TEXT PRIMARY KEY, Anchor TEXT);
DELETE FROM LShufWork_CivicGP;
INSERT OR IGNORE INTO LShufWork_CivicGP (UnitType, Anchor)
  SELECT f.UnitType, COALESCE(
      (SELECT q.BuildingType1 FROM UniqueQuarters q WHERE q.UniqueQuarterType = g.UniqueQuarterType AND q.BuildingType1 IN (SELECT u.TargetType FROM ProgressionTreeNodeUnlocks u JOIN ProgressionTreeNodes n
    ON n.ProgressionTreeNodeType = u.ProgressionTreeNodeType WHERE n.ProgressionTree LIKE 'TREE\_CIVICS\_%' ESCAPE '\' AND n.ProgressionTree NOT LIKE '%\_MAIN' ESCAPE '\')),
      CASE WHEN g.ConstructibleType IN (SELECT u.TargetType FROM ProgressionTreeNodeUnlocks u JOIN ProgressionTreeNodes n
    ON n.ProgressionTreeNodeType = u.ProgressionTreeNodeType WHERE n.ProgressionTree LIKE 'TREE\_CIVICS\_%' ESCAPE '\' AND n.ProgressionTree NOT LIKE '%\_MAIN' ESCAPE '\') THEN g.ConstructibleType END)
  FROM GreatPersonClasses g JOIN Units b ON (g.UnitType = b.UnitType OR g.UnitType LIKE b.UnitType || '\_%' ESCAPE '\')
  JOIN LShufWork_CivInfo i ON i.Base = b.TraitType
  JOIN Units f ON f.TraitType = b.TraitType AND (f.UnitType = b.UnitType OR f.UnitType LIKE b.UnitType || '\_%' ESCAPE '\')
  WHERE NOT EXISTS (SELECT 1 FROM Units p WHERE p.TraitType = b.TraitType AND b.UnitType LIKE p.UnitType || '\_%' ESCAPE '\')
    AND COALESCE(
      (SELECT q.BuildingType1 FROM UniqueQuarters q WHERE q.UniqueQuarterType = g.UniqueQuarterType AND q.BuildingType1 IN (SELECT u.TargetType FROM ProgressionTreeNodeUnlocks u JOIN ProgressionTreeNodes n
    ON n.ProgressionTreeNodeType = u.ProgressionTreeNodeType WHERE n.ProgressionTree LIKE 'TREE\_CIVICS\_%' ESCAPE '\' AND n.ProgressionTree NOT LIKE '%\_MAIN' ESCAPE '\')),
      CASE WHEN g.ConstructibleType IN (SELECT u.TargetType FROM ProgressionTreeNodeUnlocks u JOIN ProgressionTreeNodes n
    ON n.ProgressionTreeNodeType = u.ProgressionTreeNodeType WHERE n.ProgressionTree LIKE 'TREE\_CIVICS\_%' ESCAPE '\' AND n.ProgressionTree NOT LIKE '%\_MAIN' ESCAPE '\') THEN g.ConstructibleType END) IS NOT NULL;
-- A unit family a civic of the civ's own tree names in a modifier (LShufCivUnitLinks, CONTRACTS 23 R1: Sengoku's
-- Samurai and Kinsei) belongs to that civic the same way; its anchor is the civic.
INSERT OR IGNORE INTO LShufWork_CivicGP (UnitType, Anchor)
  SELECT f.UnitType, l.NodeType FROM LShufCivUnitLinks l JOIN Units b ON b.UnitType = l.UnitType
  JOIN LShufWork_CivInfo i ON i.Base = b.TraitType
  JOIN ProgressionTreeNodes n ON n.ProgressionTreeNodeType = l.NodeType AND n.ProgressionTree = i.Tree
  JOIN Units f ON f.TraitType = b.TraitType AND (f.UnitType = b.UnitType OR f.UnitType LIKE b.UnitType || '\_%' ESCAPE '\');
INSERT OR IGNORE INTO LShufWork_CivicUnit (UnitType) SELECT UnitType FROM LShufWork_CivicGP;
INSERT OR IGNORE INTO LShufWork_CivicUnit (UnitType)
  SELECT f.UnitType FROM Units b JOIN LShufWork_CivInfo i ON i.Base = b.TraitType
  JOIN Units f ON f.TraitType = b.TraitType AND (f.UnitType = b.UnitType OR f.UnitType LIKE b.UnitType || '\_%' ESCAPE '\')
  WHERE NOT EXISTS (SELECT 1 FROM Units p WHERE p.TraitType = b.TraitType AND b.UnitType LIKE p.UnitType || '\_%' ESCAPE '\')
    AND EXISTS (SELECT 1 FROM Units m WHERE m.TraitType = b.TraitType AND (m.UnitType = b.UnitType OR m.UnitType LIKE b.UnitType || '\_%' ESCAPE '\')
      AND m.UnitType IN (SELECT u.TargetType FROM ProgressionTreeNodeUnlocks u JOIN ProgressionTreeNodes n
    ON n.ProgressionTreeNodeType = u.ProgressionTreeNodeType WHERE n.ProgressionTree LIKE 'TREE\_CIVICS\_%' ESCAPE '\' AND n.ProgressionTree NOT LIKE '%\_MAIN' ESCAPE '\'))
    AND NOT EXISTS (SELECT 1 FROM Units m WHERE m.TraitType = b.TraitType AND (m.UnitType = b.UnitType OR m.UnitType LIKE b.UnitType || '\_%' ESCAPE '\')
      AND m.UnitType IN (SELECT u.TargetType FROM ProgressionTreeNodeUnlocks u JOIN ProgressionTreeNodes n
    ON n.ProgressionTreeNodeType = u.ProgressionTreeNodeType WHERE NOT (n.ProgressionTree LIKE 'TREE\_CIVICS\_%' ESCAPE '\' AND n.ProgressionTree NOT LIKE '%\_MAIN' ESCAPE '\')));
-- Each civ's own civics, one row per node of its tree (CONTRACTS 21).
CREATE TABLE IF NOT EXISTS LShufWork_CivNode (Node TEXT PRIMARY KEY, Civ TEXT, Age TEXT, Cost INTEGER);
DELETE FROM LShufWork_CivNode;
INSERT OR IGNORE INTO LShufWork_CivNode (Node, Civ, Age, Cost)
  SELECT n.ProgressionTreeNodeType, i.Civ, i.Age, n.Cost FROM ProgressionTreeNodes n JOIN LShufWork_CivInfo i ON i.Tree = n.ProgressionTree;
-- Unit families and improvements only: buildings and quarters move with the civics tree (CONTRACTS 18).
CREATE TABLE IF NOT EXISTS LShufWork_CivUnique (Type TEXT PRIMARY KEY, Kind TEXT, Civ TEXT);
DELETE FROM LShufWork_CivUnique;
INSERT OR IGNORE INTO LShufWork_CivUnique (Type, Kind, Civ)
  SELECT u.UnitType, 'unit', i.Civ FROM Units u JOIN LShufWork_CivInfo i ON i.Base = u.TraitType
  WHERE NOT EXISTS (SELECT 1 FROM Units p WHERE p.TraitType = u.TraitType AND u.UnitType LIKE p.UnitType || '\_%' ESCAPE '\')
    AND u.UnitType NOT IN (SELECT UnitType FROM LShufWork_CivicUnit)
    AND NOT (u.CanTrain = 0 AND u.UnitType IN (SELECT UnitType FROM GreatPersonClasses));
-- Since 1.5.1 a civ's great person can't be trained: the ability grants it (TRAIT_MOD_GRANT_*), so it isn't a card.
INSERT OR IGNORE INTO LShufWork_CivUnique (Type, Kind, Civ)
  SELECT m.ConstructibleType, 'improvement', i.Civ FROM Improvements m JOIN LShufWork_CivInfo i ON i.Base = m.TraitType
  WHERE m.ConstructibleType NOT IN (SELECT u.TargetType FROM ProgressionTreeNodeUnlocks u
    JOIN ProgressionTreeNodes n ON n.ProgressionTreeNodeType = u.ProgressionTreeNodeType
    WHERE n.ProgressionTree LIKE 'TREE\_CIVICS\_%' ESCAPE '\' AND n.ProgressionTree NOT LIKE '%\_MAIN' ESCAPE '\');
CREATE TABLE IF NOT EXISTS LShufWork_CivNodeEdge (A TEXT, B TEXT, PRIMARY KEY (A, B));
DELETE FROM LShufWork_CivNodeEdge;
INSERT OR IGNORE INTO LShufWork_CivNodeEdge (A, B) SELECT x.A, x.B FROM
  (SELECT (SELECT MIN(u.ProgressionTreeNodeType) FROM ProgressionTreeNodeUnlocks u
      JOIN LShufWork_CivNode c ON c.Node = u.ProgressionTreeNodeType WHERE u.TargetType = q.BuildingType1) AS A, (SELECT MIN(u.ProgressionTreeNodeType) FROM ProgressionTreeNodeUnlocks u
      JOIN LShufWork_CivNode c ON c.Node = u.ProgressionTreeNodeType WHERE u.TargetType = q.BuildingType2) AS B FROM UniqueQuarters q) x
  JOIN LShufWork_CivNode a ON a.Node = x.A JOIN LShufWork_CivNode b ON b.Node = x.B WHERE a.Civ = b.Civ AND x.A <> x.B;
INSERT OR IGNORE INTO LShufWork_CivNodeEdge (A, B) SELECT l.NodeType, l.NeedsNodeType FROM LShufCivLinks l
  JOIN LShufWork_CivNode a ON a.Node = l.NodeType JOIN LShufWork_CivNode b ON b.Node = l.NeedsNodeType
  WHERE a.Civ = b.Civ AND l.NodeType <> l.NeedsNodeType;
INSERT OR IGNORE INTO LShufWork_CivNodeEdge (A, B) SELECT B, A FROM LShufWork_CivNodeEdge;
CREATE TABLE IF NOT EXISTS LShufWork_CivNodeLead (Node TEXT PRIMARY KEY, Civ TEXT, Lead TEXT);
DELETE FROM LShufWork_CivNodeLead;
INSERT OR IGNORE INTO LShufWork_CivNodeLead (Node, Civ, Lead) SELECT Node, Civ, Node FROM LShufWork_CivNode;
UPDATE LShufWork_CivNodeLead SET Lead = MIN(Lead, COALESCE((SELECT MIN(l.Lead) FROM LShufWork_CivNodeEdge e
    JOIN LShufWork_CivNodeLead l ON l.Node = e.B WHERE e.A = LShufWork_CivNodeLead.Node), Lead));
UPDATE LShufWork_CivNodeLead SET Lead = MIN(Lead, COALESCE((SELECT MIN(l.Lead) FROM LShufWork_CivNodeEdge e
    JOIN LShufWork_CivNodeLead l ON l.Node = e.B WHERE e.A = LShufWork_CivNodeLead.Node), Lead));
UPDATE LShufWork_CivNodeLead SET Lead = MIN(Lead, COALESCE((SELECT MIN(l.Lead) FROM LShufWork_CivNodeEdge e
    JOIN LShufWork_CivNodeLead l ON l.Node = e.B WHERE e.A = LShufWork_CivNodeLead.Node), Lead));
UPDATE LShufWork_CivNodeLead SET Lead = MIN(Lead, COALESCE((SELECT MIN(l.Lead) FROM LShufWork_CivNodeEdge e
    JOIN LShufWork_CivNodeLead l ON l.Node = e.B WHERE e.A = LShufWork_CivNodeLead.Node), Lead));
UPDATE LShufWork_CivNodeLead SET Lead = MIN(Lead, COALESCE((SELECT MIN(l.Lead) FROM LShufWork_CivNodeEdge e
    JOIN LShufWork_CivNodeLead l ON l.Node = e.B WHERE e.A = LShufWork_CivNodeLead.Node), Lead));
UPDATE LShufWork_CivNodeLead SET Lead = MIN(Lead, COALESCE((SELECT MIN(l.Lead) FROM LShufWork_CivNodeEdge e
    JOIN LShufWork_CivNodeLead l ON l.Node = e.B WHERE e.A = LShufWork_CivNodeLead.Node), Lead));
UPDATE LShufWork_CivNodeLead SET Lead = MIN(Lead, COALESCE((SELECT MIN(l.Lead) FROM LShufWork_CivNodeEdge e
    JOIN LShufWork_CivNodeLead l ON l.Node = e.B WHERE e.A = LShufWork_CivNodeLead.Node), Lead));
UPDATE LShufWork_CivNodeLead SET Lead = MIN(Lead, COALESCE((SELECT MIN(l.Lead) FROM LShufWork_CivNodeEdge e
    JOIN LShufWork_CivNodeLead l ON l.Node = e.B WHERE e.A = LShufWork_CivNodeLead.Node), Lead));
CREATE TABLE IF NOT EXISTS LShufWork_CivRider (Rider TEXT PRIMARY KEY, Kind TEXT, Civ TEXT, Lead TEXT);
DELETE FROM LShufWork_CivRider;
INSERT OR IGNORE INTO LShufWork_CivRider (Rider, Kind, Civ, Lead)
  SELECT 'CIVNODE_' || Node, 'civic', Civ, 'CIVNODE_' || Lead FROM LShufWork_CivNodeLead WHERE Lead <> Node;
INSERT OR IGNORE INTO LShufWork_CivRider (Rider, Kind, Civ, Lead)
  SELECT 'CIVUNQ_' || iu.Type, 'unique', iu.Civ, 'CIVUNQ_' || lu.Type FROM Unit_BuildConstructibles b
  JOIN LShufWork_CivUnique iu ON iu.Type = b.ConstructibleType
  JOIN LShufWork_CivUnique lu ON lu.Kind = 'unit' AND lu.Civ = iu.Civ AND lu.Type <> iu.Type AND (b.UnitType = lu.Type OR b.UnitType LIKE lu.Type || '\_%' ESCAPE '\')
  WHERE (SELECT COUNT(*) FROM Unit_BuildConstructibles o WHERE o.ConstructibleType = b.ConstructibleType) = 1;

CREATE TABLE IF NOT EXISTS LShufWork_CivTaken (PieceId TEXT PRIMARY KEY);
DELETE FROM LShufWork_CivTaken;
CREATE TABLE IF NOT EXISTS LShufWork_CivSwap (Slot INTEGER, Builder TEXT, Source TEXT);
DELETE FROM LShufWork_CivSwap;
CREATE TABLE IF NOT EXISTS LShufWork_CivCSwap (Slot INTEGER, Builder TEXT, Source TEXT);
DELETE FROM LShufWork_CivCSwap;
CREATE TABLE IF NOT EXISTS LShufWork_CivTake (Slot INTEGER, Builder TEXT, Type TEXT, Source TEXT, SortIndex INTEGER);
DELETE FROM LShufWork_CivTake;
CREATE TABLE IF NOT EXISTS LShufWork_CivPTake (Slot INTEGER, Builder TEXT, PieceId TEXT PRIMARY KEY, Source TEXT, BI INTEGER);
DELETE FROM LShufWork_CivPTake;
CREATE TABLE IF NOT EXISTS LShufWork_CivNTake (Slot INTEGER, Builder TEXT, Node TEXT PRIMARY KEY, Source TEXT, SortIndex INTEGER);
DELETE FROM LShufWork_CivNTake;
CREATE TABLE IF NOT EXISTS LShufWork_CivPieced (Civ TEXT PRIMARY KEY);
DELETE FROM LShufWork_CivPieced;
  SELECT 1, (SELECT b.Civ FROM LShufWork_Build b WHERE b.Slot = 1 AND b.OK = 1 AND b.Civ IN (SELECT Civ FROM LShufWork_CivInfo)), (SELECT MIN(p.Arg) FROM LShufWork_BuildPiece p JOIN LShufWork_CivInfo s ON s.Civ = p.Arg
    WHERE p.Slot = 1 AND p.Kind = 'civcivics' AND s.Civ <> (SELECT b.Civ FROM LShufWork_Build b WHERE b.Slot = 1 AND b.OK = 1 AND b.Civ IN (SELECT Civ FROM LShufWork_CivInfo)) AND COALESCE(s.Play, s.Age) = (SELECT COALESCE(i.Play, i.Age) FROM LShufWork_CivInfo i WHERE i.Civ = (SELECT b.Civ FROM LShufWork_Build b WHERE b.Slot = 1 AND b.OK = 1 AND b.Civ IN (SELECT Civ FROM LShufWork_CivInfo))) AND s.Tree IS NOT NULL
      AND s.Civ NOT IN (SELECT b2.Civ FROM LShufWork_Build b2 WHERE b2.Slot < 1 AND b2.OK = 1 AND b2.Civ IN (SELECT Civ FROM LShufWork_CivInfo)) AND NOT 'CIVCIVC_' || s.Civ IN (SELECT PieceId FROM LShufWork_CivTaken))
  WHERE (SELECT b.Civ FROM LShufWork_Build b WHERE b.Slot = 1 AND b.OK = 1 AND b.Civ IN (SELECT Civ FROM LShufWork_CivInfo)) IS NOT NULL AND (SELECT i.Tree FROM LShufWork_CivInfo i WHERE i.Civ = (SELECT b.Civ FROM LShufWork_Build b WHERE b.Slot = 1 AND b.OK = 1 AND b.Civ IN (SELECT Civ FROM LShufWork_CivInfo))) IS NOT NULL AND NOT 'CIVCIVC_' || (SELECT b.Civ FROM LShufWork_Build b WHERE b.Slot = 1 AND b.OK = 1 AND b.Civ IN (SELECT Civ FROM LShufWork_CivInfo)) IN (SELECT PieceId FROM LShufWork_CivTaken);
DELETE FROM LShufWork_CivCSwap WHERE Slot = 1 AND (Builder IS NULL OR Source IS NULL);
INSERT OR IGNORE INTO LShufWork_CivTaken (PieceId) SELECT 'CIVCIVC_' || Builder FROM LShufWork_CivCSwap WHERE Slot = 1;
INSERT OR IGNORE INTO LShufWork_CivTaken (PieceId) SELECT 'CIVCIVC_' || Source FROM LShufWork_CivCSwap WHERE Slot = 1;
  SELECT 1, (SELECT b.Civ FROM LShufWork_Build b WHERE b.Slot = 1 AND b.OK = 1 AND b.Civ IN (SELECT Civ FROM LShufWork_CivInfo)), (SELECT MIN(p.Arg) FROM LShufWork_BuildPiece p JOIN LShufWork_CivInfo s ON s.Civ = p.Arg
    WHERE p.Slot = 1 AND p.Kind = 'civability' AND s.Civ <> (SELECT b.Civ FROM LShufWork_Build b WHERE b.Slot = 1 AND b.OK = 1 AND b.Civ IN (SELECT Civ FROM LShufWork_CivInfo))
      AND s.Civ NOT IN (SELECT b2.Civ FROM LShufWork_Build b2 WHERE b2.Slot < 1 AND b2.OK = 1 AND b2.Civ IN (SELECT Civ FROM LShufWork_CivInfo)) AND NOT 'CIVABIL_' || s.Civ IN (SELECT PieceId FROM LShufWork_CivTaken) AND NOT s.Civ IN (SELECT Civ FROM LShufWork_CivPieced))
  WHERE (SELECT b.Civ FROM LShufWork_Build b WHERE b.Slot = 1 AND b.OK = 1 AND b.Civ IN (SELECT Civ FROM LShufWork_CivInfo)) IS NOT NULL AND NOT 'CIVABIL_' || (SELECT b.Civ FROM LShufWork_Build b WHERE b.Slot = 1 AND b.OK = 1 AND b.Civ IN (SELECT Civ FROM LShufWork_CivInfo)) IN (SELECT PieceId FROM LShufWork_CivTaken) AND NOT (SELECT b.Civ FROM LShufWork_Build b WHERE b.Slot = 1 AND b.OK = 1 AND b.Civ IN (SELECT Civ FROM LShufWork_CivInfo)) IN (SELECT Civ FROM LShufWork_CivPieced);
DELETE FROM LShufWork_CivSwap WHERE Slot = 1 AND (Builder IS NULL OR Source IS NULL);
INSERT OR IGNORE INTO LShufWork_CivTaken (PieceId) SELECT 'CIVABIL_' || Builder FROM LShufWork_CivSwap WHERE Slot = 1;
INSERT OR IGNORE INTO LShufWork_CivTaken (PieceId) SELECT 'CIVABIL_' || Source FROM LShufWork_CivSwap WHERE Slot = 1;
  SELECT DISTINCT 1, (SELECT b.Civ FROM LShufWork_Build b WHERE b.Slot = 1 AND b.OK = 1 AND b.Civ IN (SELECT Civ FROM LShufWork_CivInfo)), u.Type, u.Civ FROM LShufWork_BuildPiece p
  JOIN LShufWork_CivUnique u ON 'CIVUNQ_' || u.Type = COALESCE((SELECT w.Lead FROM LShufWork_CivRider w WHERE w.Rider = 'CIVUNQ_' || p.Arg), 'CIVUNQ_' || p.Arg)
  WHERE p.Slot = 1 AND p.Kind = 'civunique' AND (SELECT b.Civ FROM LShufWork_Build b WHERE b.Slot = 1 AND b.OK = 1 AND b.Civ IN (SELECT Civ FROM LShufWork_CivInfo)) IS NOT NULL AND u.Civ <> (SELECT b.Civ FROM LShufWork_Build b WHERE b.Slot = 1 AND b.OK = 1 AND b.Civ IN (SELECT Civ FROM LShufWork_CivInfo)) AND NOT 'CIVUNQ_' || u.Type IN (SELECT Rider FROM LShufWork_CivRider)
    AND (SELECT COALESCE(i.Play, i.Age) FROM LShufWork_CivInfo i WHERE i.Civ = u.Civ) = (SELECT COALESCE(i.Play, i.Age) FROM LShufWork_CivInfo i WHERE i.Civ = (SELECT b.Civ FROM LShufWork_Build b WHERE b.Slot = 1 AND b.OK = 1 AND b.Civ IN (SELECT Civ FROM LShufWork_CivInfo))) AND NOT 'CIVUNQ_' || u.Type IN (SELECT PieceId FROM LShufWork_CivTaken);
INSERT OR IGNORE INTO LShufWork_CivTaken (PieceId) SELECT 'CIVUNQ_' || Type FROM LShufWork_CivTake WHERE Slot = 1;
INSERT OR IGNORE INTO LShufWork_CivTaken (PieceId) SELECT w.Rider FROM LShufWork_CivRider w
  WHERE w.Lead IN (SELECT 'CIVUNQ_' || Type FROM LShufWork_CivTake WHERE Slot = 1);
  SELECT 1, (SELECT b.Civ FROM LShufWork_Build b WHERE b.Slot = 1 AND b.OK = 1 AND b.Civ IN (SELECT Civ FROM LShufWork_CivInfo)), m.PieceId, m.CivilizationType, m.BulletIndex FROM LShufWork_BuildPiece p
  JOIN LShufCivMapping m ON m.PieceId = p.PieceId JOIN LShufWork_CivInfo s ON s.Civ = m.CivilizationType
  WHERE p.Slot = 1 AND p.Kind = 'civbullet' AND (SELECT CA FROM LShufWork_Cfg) = 'LSHUF_CA_SPLIT' AND (SELECT b.Civ FROM LShufWork_Build b WHERE b.Slot = 1 AND b.OK = 1 AND b.Civ IN (SELECT Civ FROM LShufWork_CivInfo)) IS NOT NULL AND NOT 'CIVABIL_' || (SELECT b.Civ FROM LShufWork_Build b WHERE b.Slot = 1 AND b.OK = 1 AND b.Civ IN (SELECT Civ FROM LShufWork_CivInfo)) IN (SELECT PieceId FROM LShufWork_CivTaken)
    AND (COALESCE(s.Play, s.Age) = (SELECT COALESCE(i.Play, i.Age) FROM LShufWork_CivInfo i WHERE i.Civ = (SELECT b.Civ FROM LShufWork_Build b WHERE b.Slot = 1 AND b.OK = 1 AND b.Civ IN (SELECT Civ FROM LShufWork_CivInfo))) OR m.PieceId NOT IN ('CIVILIZATION_FRENCH_EMPIRE__B01', 'CIVILIZATION_JOSEON__B02', 'CIVILIZATION_MEXICO__B02', 'CIVILIZATION_NEPAL__B02', 'CIVILIZATION_ABBASID__B03', 'CIVILIZATION_AKSUM__B04', 'CIVILIZATION_AMERICA__B03', 'CIVILIZATION_ASSYRIA__B03', 'CIVILIZATION_BABYLON__B03', 'CIVILIZATION_BUGANDA__B04', 'CIVILIZATION_BULGARIA__B03', 'CIVILIZATION_CARTHAGE__B03', 'CIVILIZATION_CHOLA__B05', 'CIVILIZATION_DAI_VIET__B03', 'CIVILIZATION_EGYPT__B03', 'CIVILIZATION_ENGLAND__B03', 'CIVILIZATION_FRENCH_EMPIRE__B02', 'CIVILIZATION_GAUL__B04', 'CIVILIZATION_GORYEO__B04', 'CIVILIZATION_GREAT_BRITAIN__B04', 'CIVILIZATION_GREECE__B04', 'CIVILIZATION_HAN__B03', 'CIVILIZATION_HAWAII__B03', 'CIVILIZATION_HEIAN__B02', 'CIVILIZATION_ICELAND__B05', 'CIVILIZATION_INCA__B04', 'CIVILIZATION_JOSEON__B05', 'CIVILIZATION_KHMER__B03', 'CIVILIZATION_MAJAPAHIT__B04', 'CIVILIZATION_MAURYA__B03', 'CIVILIZATION_MAYA__B03', 'CIVILIZATION_MEIJI__B02', 'CIVILIZATION_MEXICO__B03', 'CIVILIZATION_MING__B04', 'CIVILIZATION_MISSISSIPPIAN__B03', 'CIVILIZATION_MONGOLIA__B03', 'CIVILIZATION_MUGHAL__B04', 'CIVILIZATION_NEPAL__B03', 'CIVILIZATION_NORMAN__B03', 'CIVILIZATION_OTTOMANS__B03', 'CIVILIZATION_PERSIA__B03', 'CIVILIZATION_PIRATE_REPUBLIC__B05', 'CIVILIZATION_PRUSSIA__B03', 'CIVILIZATION_QAJAR__B03', 'CIVILIZATION_QING__B04', 'CIVILIZATION_ROME__B03', 'CIVILIZATION_RUSSIA__B03', 'CIVILIZATION_SENGOKU__B04', 'CIVILIZATION_SHAWNEE__B03', 'CIVILIZATION_SIAM__B04', 'CIVILIZATION_SILLA__B03', 'CIVILIZATION_SONGHAI__B04', 'CIVILIZATION_SPAIN__B03', 'CIVILIZATION_TONGA__B04')) AND m.Kind = 'bullet' AND m.Movable = 1 AND m.Age = s.Age
    AND m.PieceId NOT IN (SELECT d.PieceId FROM LShufCivPieceDead d WHERE d.Age = (SELECT Value FROM LShufOptions WHERE Name = 'Age')) AND NOT 'CIVABIL_' || s.Civ IN (SELECT PieceId FROM LShufWork_CivTaken) AND NOT m.PieceId IN (SELECT PieceId FROM LShufWork_CivTaken);
INSERT OR IGNORE INTO LShufWork_CivTaken (PieceId) SELECT PieceId FROM LShufWork_CivPTake WHERE Slot = 1;
INSERT OR IGNORE INTO LShufWork_CivPieced (Civ) SELECT Source FROM LShufWork_CivPTake WHERE Slot = 1;
  SELECT DISTINCT 1, (SELECT b.Civ FROM LShufWork_Build b WHERE b.Slot = 1 AND b.OK = 1 AND b.Civ IN (SELECT Civ FROM LShufWork_CivInfo)), c.Node, c.Civ FROM LShufWork_BuildPiece p
  JOIN LShufWork_CivNode c ON 'CIVNODE_' || c.Node = COALESCE((SELECT w.Lead FROM LShufWork_CivRider w WHERE w.Rider = 'CIVNODE_' || p.Arg), 'CIVNODE_' || p.Arg)
  WHERE p.Slot = 1 AND p.Kind = 'civcivic' AND (SELECT b.Civ FROM LShufWork_Build b WHERE b.Slot = 1 AND b.OK = 1 AND b.Civ IN (SELECT Civ FROM LShufWork_CivInfo)) IS NOT NULL AND c.Civ <> (SELECT b.Civ FROM LShufWork_Build b WHERE b.Slot = 1 AND b.OK = 1 AND b.Civ IN (SELECT Civ FROM LShufWork_CivInfo)) AND NOT 'CIVNODE_' || c.Node IN (SELECT Rider FROM LShufWork_CivRider)
    AND (SELECT COALESCE(i.Play, i.Age) FROM LShufWork_CivInfo i WHERE i.Civ = c.Civ) = (SELECT COALESCE(i.Play, i.Age) FROM LShufWork_CivInfo i WHERE i.Civ = (SELECT b.Civ FROM LShufWork_Build b WHERE b.Slot = 1 AND b.OK = 1 AND b.Civ IN (SELECT Civ FROM LShufWork_CivInfo))) AND NOT 'CIVNODE_' || c.Node IN (SELECT PieceId FROM LShufWork_CivTaken)
