UPDATE LShufWork_CivShuf SET ADonor = NULL WHERE ADonor = Civ;
UPDATE LShufWork_CivShuf SET TDonor = NULL WHERE TDonor = Civ;
UPDATE LShufWork_CivShuf SET UDonor = NULL WHERE UDonor = Civ;
UPDATE LShufWork_CivShuf SET CDonor = NULL WHERE CDonor = Civ;
CREATE TABLE IF NOT EXISTS LShufWork_CivShufU (Civ TEXT, Type TEXT, Donor TEXT, SortIndex INTEGER, PRIMARY KEY (Civ, Type));
DELETE FROM LShufWork_CivShufU;
INSERT OR IGNORE INTO LShufWork_CivShufU (Civ, Type, Donor) SELECT s.Civ, u.Type, s.UDonor FROM LShufWork_CivShuf s
  JOIN LShufWork_CivUnique u ON u.Civ = s.UDonor WHERE s.UDonor IS NOT NULL AND NOT 'CIVUNQ_' || u.Type IN (SELECT PieceId FROM LShufWork_CivTaken)
    AND NOT 'CIVUNQ_' || u.Type IN (SELECT Rider FROM LShufWork_CivRider);
UPDATE LShufWork_CivShufU SET SortIndex = (SELECT COUNT(*) FROM LShufWork_CivShufU o WHERE o.Civ = LShufWork_CivShufU.Civ AND (o.Type < LShufWork_CivShufU.Type)) WHERE 1 = 1;

CREATE TABLE IF NOT EXISTS LShufWork_CivPc (PieceId TEXT PRIMARY KEY, Civ TEXT, Age TEXT, BI INTEGER, Value INTEGER, DV INTEGER, Rank INTEGER, K INTEGER, DeckOrd INTEGER, Taken INTEGER);
DELETE FROM LShufWork_CivPc;
  SELECT m.PieceId, m.CivilizationType, m.Age, COALESCE(m.BulletIndex, 0), COALESCE(m.Value, 1), m.PieceId IN (SELECT PieceId FROM LShufWork_CivTaken)
  FROM LShufCivMapping m JOIN LShufWork_CivInfo i ON i.Civ = m.CivilizationType
  WHERE (SELECT CA FROM LShufWork_Cfg) = 'LSHUF_CA_SPLIT' AND m.Kind = 'bullet' AND m.Movable = 1 AND m.Age = i.Age
    AND m.PieceId NOT IN (SELECT d.PieceId FROM LShufCivPieceDead d WHERE d.Age = (SELECT Value FROM LShufOptions WHERE Name = 'Age')) AND NOT 'CIVABIL_' || i.Civ IN (SELECT PieceId FROM LShufWork_CivTaken)
    AND m.PieceId NOT IN (SELECT PieceId FROM LShufBoundPieces);
UPDATE LShufWork_CivPc SET DV = CASE WHEN (SELECT Balanced FROM LShufWork_Cfg) = 1 THEN Value ELSE 0 END;
UPDATE LShufWork_CivPc SET Rank = (SELECT COUNT(*) FROM LShufWork_CivPc o WHERE 1 = 1 AND (o.PieceId < LShufWork_CivPc.PieceId)) WHERE 1 = 1;
UPDATE LShufWork_CivPc SET K = ((((((((((SELECT Seed FROM LShufWork_Cfg)) * 7919 + (16) * 104729 + (Rank) * 1299709 + 1) % 67108859) * ((((SELECT Seed FROM LShufWork_Cfg)) * 7919 + (16) * 104729 + (Rank) * 1299709 + 1) % 67108859)) + 1013904223) % 67108859) * (((((((SELECT Seed FROM LShufWork_Cfg)) * 7919 + (16) * 104729 + (Rank) * 1299709 + 1) % 67108859) * ((((SELECT Seed FROM LShufWork_Cfg)) * 7919 + (16) * 104729 + (Rank) * 1299709 + 1) % 67108859)) + 1013904223) % 67108859)) + 1664525) % 67108859);
UPDATE LShufWork_CivPc SET DeckOrd = (SELECT COUNT(*) FROM LShufWork_CivPc o WHERE 1 = 1 AND (o.DV > LShufWork_CivPc.DV OR (o.DV = LShufWork_CivPc.DV AND (o.K < LShufWork_CivPc.K OR (o.K = LShufWork_CivPc.K AND (o.PieceId < LShufWork_CivPc.PieceId)))))) WHERE Taken = 0;
CREATE TABLE IF NOT EXISTS LShufWork_CivPSlot (Civ TEXT PRIMARY KEY, Age TEXT, N INTEGER, Rank INTEGER, K INTEGER);
DELETE FROM LShufWork_CivPSlot;
  WHERE Civ NOT IN (SELECT Builder FROM LShufWork_CivPTake) GROUP BY Civ, Age;
UPDATE LShufWork_CivPSlot SET Rank = (SELECT COUNT(*) FROM LShufWork_CivPSlot o WHERE 1 = 1 AND (o.Civ < LShufWork_CivPSlot.Civ)) WHERE 1 = 1;
UPDATE LShufWork_CivPSlot SET K = ((((((((((SELECT Seed FROM LShufWork_Cfg)) * 7919 + (16) * 104729 + (Rank) * 1299709 + 1) % 67108859) * ((((SELECT Seed FROM LShufWork_Cfg)) * 7919 + (16) * 104729 + (Rank) * 1299709 + 1) % 67108859)) + 1013904223) % 67108859) * (((((((SELECT Seed FROM LShufWork_Cfg)) * 7919 + (16) * 104729 + (Rank) * 1299709 + 1) % 67108859) * ((((SELECT Seed FROM LShufWork_Cfg)) * 7919 + (16) * 104729 + (Rank) * 1299709 + 1) % 67108859)) + 1013904223) % 67108859)) + 1664525) % 67108859);
CREATE TABLE IF NOT EXISTS LShufWork_CivPDealt (PieceId TEXT PRIMARY KEY, Civ TEXT, FromCiv TEXT, Value INTEGER);
DELETE FROM LShufWork_CivPDealt;
DROP VIEW IF EXISTS LShufWork_CivNextPiece;
CREATE VIEW LShufWork_CivNextPiece AS SELECT c.PieceId AS PieceId, c.Civ AS FromCiv, c.Value AS Value, s.Civ AS Holder
  FROM (SELECT p.PieceId, p.Civ, p.Age, p.Value FROM LShufWork_CivPc p WHERE p.Taken = 0
    AND NOT EXISTS (SELECT 1 FROM LShufWork_CivPDealt d WHERE d.PieceId = p.PieceId) ORDER BY p.DeckOrd LIMIT 1) c
  LEFT JOIN LShufWork_CivPSlot s ON s.Age = c.Age AND (SELECT COUNT(*) FROM LShufWork_CivPDealt d WHERE d.Civ = s.Civ) < s.N
  ORDER BY CASE WHEN s.Civ = c.Civ THEN 1 ELSE 0 END,
    CASE WHEN (SELECT Balanced FROM LShufWork_Cfg) = 1 THEN (COALESCE((SELECT SUM(d.Value) FROM LShufWork_CivPDealt d WHERE d.Civ = s.Civ), 0) * 100) / s.N ELSE 0 END, s.K, s.Civ
  LIMIT 1;
CREATE TABLE IF NOT EXISTS LShufWork_CivHeld (Civ TEXT, PieceId TEXT, FromCiv TEXT, BI INTEGER, IsRest INTEGER, SortIndex INTEGER, PRIMARY KEY (Civ, PieceId));
DELETE FROM LShufWork_CivHeld;
INSERT OR IGNORE INTO LShufWork_CivHeld (Civ, PieceId, FromCiv, BI, IsRest) SELECT t.Builder, t.PieceId, t.Source, t.BI, 0 FROM LShufWork_CivPTake t;
INSERT OR IGNORE INTO LShufWork_CivHeld (Civ, PieceId, FromCiv, BI, IsRest) SELECT d.Civ, d.PieceId, d.FromCiv, p.BI, 0
  FROM LShufWork_CivPDealt d JOIN LShufWork_CivPc p ON p.PieceId = d.PieceId WHERE d.Civ IS NOT NULL;
INSERT OR IGNORE INTO LShufWork_CivHeld (Civ, PieceId, FromCiv, BI, IsRest) SELECT Civ, Civ || '__REST', Civ, 0, 1 FROM LShufWork_CivPSlot;
UPDATE LShufWork_CivHeld SET SortIndex = (SELECT COUNT(*) FROM LShufWork_CivHeld o WHERE o.Civ = LShufWork_CivHeld.Civ AND (o.IsRest < LShufWork_CivHeld.IsRest OR (o.IsRest = LShufWork_CivHeld.IsRest AND (o.FromCiv < LShufWork_CivHeld.FromCiv OR (o.FromCiv = LShufWork_CivHeld.FromCiv AND (o.BI < LShufWork_CivHeld.BI OR (o.BI = LShufWork_CivHeld.BI AND (o.PieceId < LShufWork_CivHeld.PieceId)))))))) WHERE 1 = 1;

CREATE TABLE IF NOT EXISTS LShufWork_CivNP (PieceId TEXT PRIMARY KEY, Civ TEXT, Age TEXT, Value INTEGER, DV INTEGER, Rank INTEGER, K INTEGER, DeckOrd INTEGER, Taken INTEGER);
DELETE FROM LShufWork_CivNP;
INSERT OR IGNORE INTO LShufWork_CivNP (PieceId, Civ, Age, Value, Taken) SELECT 'CIVNODE_' || c.Node, c.Civ, (SELECT COALESCE(i.Play, i.Age) FROM LShufWork_CivInfo i WHERE i.Civ = c.Civ), COALESCE(c.Cost, 0) + COALESCE((SELECT SUM(COALESCE(m.Cost, 0)) FROM LShufWork_CivNodeLead l
    JOIN LShufWork_CivNode m ON m.Node = l.Node WHERE l.Lead = c.Node AND l.Node <> c.Node), 0), CASE WHEN 'CIVNODE_' || c.Node IN (SELECT PieceId FROM LShufWork_CivTaken) THEN 1 ELSE 0 END
  FROM LShufWork_CivNode c WHERE (SELECT CC FROM LShufWork_Cfg) = 'LSHUF_CC_SPLIT' AND c.Civ IN (SELECT Civ FROM LShufWork_CivInfo) AND NOT 'CIVCIVC_' || c.Civ IN (SELECT PieceId FROM LShufWork_CivTaken) AND NOT 'CIVNODE_' || c.Node IN (SELECT Rider FROM LShufWork_CivRider);
UPDATE LShufWork_CivNP SET DV = CASE WHEN (SELECT Balanced FROM LShufWork_Cfg) = 1 THEN Value ELSE 0 END;
UPDATE LShufWork_CivNP SET Rank = (SELECT COUNT(*) FROM LShufWork_CivNP o WHERE 1 = 1 AND (o.PieceId < LShufWork_CivNP.PieceId)) WHERE 1 = 1;
UPDATE LShufWork_CivNP SET K = ((((((((((SELECT Seed FROM LShufWork_Cfg)) * 7919 + (17) * 104729 + (Rank) * 1299709 + 1) % 67108859) * ((((SELECT Seed FROM LShufWork_Cfg)) * 7919 + (17) * 104729 + (Rank) * 1299709 + 1) % 67108859)) + 1013904223) % 67108859) * (((((((SELECT Seed FROM LShufWork_Cfg)) * 7919 + (17) * 104729 + (Rank) * 1299709 + 1) % 67108859) * ((((SELECT Seed FROM LShufWork_Cfg)) * 7919 + (17) * 104729 + (Rank) * 1299709 + 1) % 67108859)) + 1013904223) % 67108859)) + 1664525) % 67108859);
UPDATE LShufWork_CivNP SET DeckOrd = (SELECT COUNT(*) FROM LShufWork_CivNP o WHERE 1 = 1 AND (o.DV > LShufWork_CivNP.DV OR (o.DV = LShufWork_CivNP.DV AND (o.K < LShufWork_CivNP.K OR (o.K = LShufWork_CivNP.K AND (o.PieceId < LShufWork_CivNP.PieceId)))))) WHERE Taken = 0;
CREATE TABLE IF NOT EXISTS LShufWork_CivNPSlot (Civ TEXT PRIMARY KEY, Age TEXT, N INTEGER, Rank INTEGER, K INTEGER);
DELETE FROM LShufWork_CivNPSlot;
INSERT OR IGNORE INTO LShufWork_CivNPSlot (Civ, Age, N) SELECT c.Civ, (SELECT COALESCE(i.Play, i.Age) FROM LShufWork_CivInfo i WHERE i.Civ = c.Civ), COUNT(*) FROM LShufWork_CivNode c WHERE (SELECT CC FROM LShufWork_Cfg) = 'LSHUF_CC_SPLIT' AND c.Civ IN (SELECT Civ FROM LShufWork_CivInfo) AND NOT 'CIVCIVC_' || c.Civ IN (SELECT PieceId FROM LShufWork_CivTaken) AND NOT 'CIVNODE_' || c.Node IN (SELECT Rider FROM LShufWork_CivRider)
    AND c.Civ NOT IN (SELECT Builder FROM LShufWork_CivNTake) GROUP BY c.Civ;
UPDATE LShufWork_CivNPSlot SET Rank = (SELECT COUNT(*) FROM LShufWork_CivNPSlot o WHERE 1 = 1 AND (o.Civ < LShufWork_CivNPSlot.Civ)) WHERE 1 = 1;
UPDATE LShufWork_CivNPSlot SET K = ((((((((((SELECT Seed FROM LShufWork_Cfg)) * 7919 + (17) * 104729 + (Rank) * 1299709 + 1) % 67108859) * ((((SELECT Seed FROM LShufWork_Cfg)) * 7919 + (17) * 104729 + (Rank) * 1299709 + 1) % 67108859)) + 1013904223) % 67108859) * (((((((SELECT Seed FROM LShufWork_Cfg)) * 7919 + (17) * 104729 + (Rank) * 1299709 + 1) % 67108859) * ((((SELECT Seed FROM LShufWork_Cfg)) * 7919 + (17) * 104729 + (Rank) * 1299709 + 1) % 67108859)) + 1013904223) % 67108859)) + 1664525) % 67108859);
CREATE TABLE IF NOT EXISTS LShufWork_CivNPDealt (PieceId TEXT PRIMARY KEY, Civ TEXT, FromCiv TEXT, Value INTEGER, SortIndex INTEGER);
DELETE FROM LShufWork_CivNPDealt;
DROP VIEW IF EXISTS LShufWork_CivNPNext;
CREATE VIEW LShufWork_CivNPNext AS SELECT c.PieceId AS PieceId, c.Civ AS FromCiv, c.Value AS Value, s.Civ AS Holder
  FROM (SELECT p.PieceId, p.Civ, p.Age, p.Value FROM LShufWork_CivNP p WHERE p.Taken = 0
    AND NOT EXISTS (SELECT 1 FROM LShufWork_CivNPDealt d WHERE d.PieceId = p.PieceId) ORDER BY p.DeckOrd LIMIT 1) c
  LEFT JOIN LShufWork_CivNPSlot s ON s.Age = c.Age AND (SELECT COUNT(*) FROM LShufWork_CivNPDealt d WHERE d.Civ = s.Civ) < s.N
  ORDER BY CASE WHEN s.Civ = c.Civ THEN 1 ELSE 0 END,
    CASE WHEN (SELECT Balanced FROM LShufWork_Cfg) = 1 THEN (COALESCE((SELECT SUM(d.Value) FROM LShufWork_CivNPDealt d WHERE d.Civ = s.Civ), 0) * 100) / s.N ELSE 0 END, s.K, s.Civ
  LIMIT 1;
DELETE FROM LShufWork_CivNPDealt WHERE Civ IS NULL;
UPDATE LShufWork_CivNPDealt SET SortIndex = (SELECT COUNT(*) FROM LShufWork_CivNPDealt o WHERE o.Civ = LShufWork_CivNPDealt.Civ AND (o.FromCiv < LShufWork_CivNPDealt.FromCiv OR (o.FromCiv = LShufWork_CivNPDealt.FromCiv AND (o.PieceId < LShufWork_CivNPDealt.PieceId)))) WHERE 1 = 1;

CREATE TABLE IF NOT EXISTS LShufWork_CivUP (PieceId TEXT PRIMARY KEY, Civ TEXT, Age TEXT, Value INTEGER, DV INTEGER, Rank INTEGER, K INTEGER, DeckOrd INTEGER, Taken INTEGER);
DELETE FROM LShufWork_CivUP;
INSERT OR IGNORE INTO LShufWork_CivUP (PieceId, Civ, Age, Value, Taken) SELECT 'CIVUNQ_' || u.Type, u.Civ, (SELECT COALESCE(i.Play, i.Age) FROM LShufWork_CivInfo i WHERE i.Civ = u.Civ), 1, CASE WHEN 'CIVUNQ_' || u.Type IN (SELECT PieceId FROM LShufWork_CivTaken) THEN 1 ELSE 0 END
  FROM LShufWork_CivUnique u WHERE (SELECT CU FROM LShufWork_Cfg) = 'LSHUF_CU_SPLIT' AND NOT 'CIVUNQ_' || u.Type IN (SELECT Rider FROM LShufWork_CivRider);
