UPDATE LShufWork_CivUP SET Rank = (SELECT COUNT(*) FROM LShufWork_CivUP o WHERE 1 = 1 AND (o.PieceId < LShufWork_CivUP.PieceId)) WHERE 1 = 1;
UPDATE LShufWork_CivUP SET K = ((((((((((SELECT Seed FROM LShufWork_Cfg)) * 7919 + (18) * 104729 + (Rank) * 1299709 + 1) % 67108859) * ((((SELECT Seed FROM LShufWork_Cfg)) * 7919 + (18) * 104729 + (Rank) * 1299709 + 1) % 67108859)) + 1013904223) % 67108859) * (((((((SELECT Seed FROM LShufWork_Cfg)) * 7919 + (18) * 104729 + (Rank) * 1299709 + 1) % 67108859) * ((((SELECT Seed FROM LShufWork_Cfg)) * 7919 + (18) * 104729 + (Rank) * 1299709 + 1) % 67108859)) + 1013904223) % 67108859)) + 1664525) % 67108859);
UPDATE LShufWork_CivUP SET DeckOrd = (SELECT COUNT(*) FROM LShufWork_CivUP o WHERE 1 = 1 AND (o.DV > LShufWork_CivUP.DV OR (o.DV = LShufWork_CivUP.DV AND (o.K < LShufWork_CivUP.K OR (o.K = LShufWork_CivUP.K AND (o.PieceId < LShufWork_CivUP.PieceId)))))) WHERE Taken = 0;
CREATE TABLE IF NOT EXISTS LShufWork_CivUPSlot (Civ TEXT PRIMARY KEY, Age TEXT, N INTEGER, Rank INTEGER, K INTEGER);
DELETE FROM LShufWork_CivUPSlot;
INSERT OR IGNORE INTO LShufWork_CivUPSlot (Civ, Age, N) SELECT u.Civ, (SELECT COALESCE(i.Play, i.Age) FROM LShufWork_CivInfo i WHERE i.Civ = u.Civ), COUNT(*) FROM LShufWork_CivUnique u WHERE (SELECT CU FROM LShufWork_Cfg) = 'LSHUF_CU_SPLIT' AND NOT 'CIVUNQ_' || u.Type IN (SELECT Rider FROM LShufWork_CivRider)
    AND u.Civ NOT IN (SELECT Builder FROM LShufWork_CivTake) GROUP BY u.Civ;
UPDATE LShufWork_CivUPSlot SET Rank = (SELECT COUNT(*) FROM LShufWork_CivUPSlot o WHERE 1 = 1 AND (o.Civ < LShufWork_CivUPSlot.Civ)) WHERE 1 = 1;
UPDATE LShufWork_CivUPSlot SET K = ((((((((((SELECT Seed FROM LShufWork_Cfg)) * 7919 + (18) * 104729 + (Rank) * 1299709 + 1) % 67108859) * ((((SELECT Seed FROM LShufWork_Cfg)) * 7919 + (18) * 104729 + (Rank) * 1299709 + 1) % 67108859)) + 1013904223) % 67108859) * (((((((SELECT Seed FROM LShufWork_Cfg)) * 7919 + (18) * 104729 + (Rank) * 1299709 + 1) % 67108859) * ((((SELECT Seed FROM LShufWork_Cfg)) * 7919 + (18) * 104729 + (Rank) * 1299709 + 1) % 67108859)) + 1013904223) % 67108859)) + 1664525) % 67108859);
CREATE TABLE IF NOT EXISTS LShufWork_CivUPDealt (PieceId TEXT PRIMARY KEY, Civ TEXT, FromCiv TEXT, Value INTEGER, SortIndex INTEGER);
DELETE FROM LShufWork_CivUPDealt;
DROP VIEW IF EXISTS LShufWork_CivUPNext;
CREATE VIEW LShufWork_CivUPNext AS SELECT c.PieceId AS PieceId, c.Civ AS FromCiv, c.Value AS Value, s.Civ AS Holder
  FROM (SELECT p.PieceId, p.Civ, p.Age, p.Value FROM LShufWork_CivUP p WHERE p.Taken = 0
    AND NOT EXISTS (SELECT 1 FROM LShufWork_CivUPDealt d WHERE d.PieceId = p.PieceId) ORDER BY p.DeckOrd LIMIT 1) c
  LEFT JOIN LShufWork_CivUPSlot s ON s.Age = c.Age AND (SELECT COUNT(*) FROM LShufWork_CivUPDealt d WHERE d.Civ = s.Civ) < s.N
  ORDER BY CASE WHEN s.Civ = c.Civ THEN 1 ELSE 0 END,
    CASE WHEN (SELECT Balanced FROM LShufWork_Cfg) = 1 THEN (COALESCE((SELECT SUM(d.Value) FROM LShufWork_CivUPDealt d WHERE d.Civ = s.Civ), 0) * 100) / s.N ELSE 0 END, s.K, s.Civ
  LIMIT 1;
DELETE FROM LShufWork_CivUPDealt WHERE Civ IS NULL;
UPDATE LShufWork_CivUPDealt SET SortIndex = (SELECT COUNT(*) FROM LShufWork_CivUPDealt o WHERE o.Civ = LShufWork_CivUPDealt.Civ AND (o.FromCiv < LShufWork_CivUPDealt.FromCiv OR (o.FromCiv = LShufWork_CivUPDealt.FromCiv AND (o.PieceId < LShufWork_CivUPDealt.PieceId)))) WHERE 1 = 1;

UPDATE LShufWork_CivTake SET SortIndex = (SELECT COUNT(*) FROM LShufWork_CivTake o WHERE o.Slot = LShufWork_CivTake.Slot AND (o.Type < LShufWork_CivTake.Type)) WHERE 1 = 1;
UPDATE LShufWork_CivNTake SET SortIndex = (SELECT COUNT(*) FROM LShufWork_CivNTake o WHERE o.Slot = LShufWork_CivNTake.Slot AND (o.Node < LShufWork_CivNTake.Node)) WHERE 1 = 1;
DELETE FROM LShufResultCivPieces;
INSERT OR IGNORE INTO LShufResultCivPieces (CivilizationType, PieceId, FromCivilization, Kind, SortIndex) SELECT Builder, 'CIVABIL_' || Source, Source, 'ability', 0 FROM LShufWork_CivSwap;
INSERT OR IGNORE INTO LShufResultCivPieces (CivilizationType, PieceId, FromCivilization, Kind, SortIndex) SELECT Source, 'CIVABIL_' || Builder, Builder, 'ability', 0 FROM LShufWork_CivSwap;
INSERT OR IGNORE INTO LShufResultCivPieces (CivilizationType, PieceId, FromCivilization, Kind, SortIndex) SELECT Builder, 'CIVCIVC_' || Source, Source, 'civics', 0 FROM LShufWork_CivCSwap;
INSERT OR IGNORE INTO LShufResultCivPieces (CivilizationType, PieceId, FromCivilization, Kind, SortIndex) SELECT Source, 'CIVCIVC_' || Builder, Builder, 'civics', 0 FROM LShufWork_CivCSwap;
INSERT OR IGNORE INTO LShufResultCivPieces (CivilizationType, PieceId, FromCivilization, Kind, SortIndex) SELECT Builder, 'CIVUNQ_' || Type, Source, 'unique', SortIndex + 1 FROM LShufWork_CivTake;
INSERT OR IGNORE INTO LShufResultCivPieces (CivilizationType, PieceId, FromCivilization, Kind, SortIndex) SELECT Civ, 'CIVABIL_' || ADonor, ADonor, 'ability', 0 FROM LShufWork_CivShuf WHERE ADonor IS NOT NULL;
INSERT OR IGNORE INTO LShufResultCivPieces (CivilizationType, PieceId, FromCivilization, Kind, SortIndex) SELECT Civ, 'CIVCIVC_' || CDonor, CDonor, 'civics', 0 FROM LShufWork_CivShuf WHERE CDonor IS NOT NULL;
INSERT OR IGNORE INTO LShufResultCivPieces (CivilizationType, PieceId, FromCivilization, Kind, SortIndex) SELECT Civ, 'CIVUNQ_' || Type, Donor, 'unique', SortIndex + 1 FROM LShufWork_CivShufU;
-- Attribute tags (CONTRACTS 30): a whole ability brings its civ's tags; abilities in pieces deal them round a cycle.
INSERT OR IGNORE INTO LShufResultCivPieces (CivilizationType, PieceId, FromCivilization, Kind, SortIndex) SELECT CivilizationType, 'CIVTAGS_' || FromCivilization, FromCivilization, 'tags', 0 FROM LShufResultCivPieces WHERE Kind = 'ability';
INSERT OR IGNORE INTO LShufResultCivPieces (CivilizationType, PieceId, FromCivilization, Kind, SortIndex) SELECT Civ, 'CIVTAGS_' || TDonor, TDonor, 'tags', 0 FROM LShufWork_CivShuf WHERE TDonor IS NOT NULL;
INSERT OR IGNORE INTO LShufResultCivPieces (CivilizationType, PieceId, FromCivilization, Kind, SortIndex) SELECT Civ, PieceId, FromCiv, CASE WHEN IsRest = 1 THEN 'remainder' ELSE 'bullet' END, SortIndex FROM LShufWork_CivHeld;
INSERT OR IGNORE INTO LShufResultCivPieces (CivilizationType, PieceId, FromCivilization, Kind, SortIndex) SELECT Builder, 'CIVNODE_' || Node, Source, 'civic', SortIndex + 1 FROM LShufWork_CivNTake;
INSERT OR IGNORE INTO LShufResultCivPieces (CivilizationType, PieceId, FromCivilization, Kind, SortIndex) SELECT Civ, PieceId, FromCiv, 'civic', SortIndex + 1 FROM LShufWork_CivNPDealt;
INSERT OR IGNORE INTO LShufResultCivPieces (CivilizationType, PieceId, FromCivilization, Kind, SortIndex) SELECT Civ, PieceId, FromCiv, 'unique', SortIndex + 1 FROM LShufWork_CivUPDealt;
-- Every rider goes with its lead (CONTRACTS 23).
INSERT OR IGNORE INTO LShufResultCivPieces (CivilizationType, PieceId, FromCivilization, Kind, SortIndex) SELECT r.CivilizationType, w.Rider, r.FromCivilization, r.Kind, r.SortIndex FROM LShufResultCivPieces r
  JOIN LShufWork_CivRider w ON w.Lead = r.PieceId AND w.Kind = r.Kind;
  SELECT 'CivBuilder' || CASE WHEN b.Slot = 1 THEN '' ELSE CAST(b.Slot AS TEXT) END, CASE WHEN b.OK = 0 THEN b.Why
    WHEN b.Civ IS NULL OR b.Civ NOT IN (SELECT Civ FROM LShufWork_CivInfo) THEN 'builder-not-in-game'
    WHEN NOT EXISTS (SELECT 1 FROM LShufWork_CivSwap s WHERE s.Slot = b.Slot)
      AND NOT EXISTS (SELECT 1 FROM LShufWork_CivCSwap s WHERE s.Slot = b.Slot)
      AND NOT EXISTS (SELECT 1 FROM LShufWork_CivTake t WHERE t.Slot = b.Slot)
      AND NOT EXISTS (SELECT 1 FROM LShufWork_CivPTake t WHERE t.Slot = b.Slot)
      AND NOT EXISTS (SELECT 1 FROM LShufWork_CivNTake t WHERE t.Slot = b.Slot) THEN 'no-pieces'
    ELSE 'ok' END FROM LShufWork_Build b ORDER BY b.Slot;
